<section class="form-section settings-component" id="media-settings">
    <div class="section-heading"><div><p class="eyebrow">Multimedia</p><h2>Upload i obrazy</h2></div><p>Transformacje i cache wariantów są niezależnymi przełącznikami.</p></div>
    <div class="settings-grid"><label>Maksymalny upload (bajty)<input type="number" name="media_max_upload_bytes" value="<?= $media->maximumUploadBytes() ?>" min="1" max="104857600" required></label><label>Jakość obrazu<input type="number" name="media_quality" value="<?= $media->quality() ?>" min="1" max="100" required></label><label>Maksymalna szerokość<input type="number" name="media_max_width" value="<?= $media->maximumWidth() ?>" min="1" max="8192" required></label><label>Maksymalna wysokość<input type="number" name="media_max_height" value="<?= $media->maximumHeight() ?>" min="1" max="8192" required></label><label>Maksymalna liczba pikseli<input type="number" name="media_max_pixels" value="<?= $media->maximumPixels() ?>" min="1" max="100000000" required></label></div>
    <div class="toggle-grid"><label class="check toggle-card"><input type="checkbox" name="strip_metadata" value="1"<?= $media->stripMetadata() ? ' checked' : '' ?>><span><strong>Usuwaj metadane</strong><small>Rekoduj JPEG i PNG przy uploadzie.</small></span></label><label class="check toggle-card"><input type="checkbox" name="transformations_enabled" value="1"<?= $media->transformationsEnabled() ? ' checked' : '' ?>><span><strong>Transformacje lokalne</strong><small>Generuj warianty przez GD.</small></span></label><label class="check toggle-card"><input type="checkbox" name="media_cache_enabled" value="1"<?= $media->cacheEnabled() ? ' checked' : '' ?>><span><strong>Cache wariantów</strong><small>Zapisuj wygenerowane pliki w storage/cache/media.</small></span></label></div>
    <fieldset class="form-card"><legend>Dozwolone MIME</legend><div class="choice-grid"><?php foreach ($mimeTypes as $mime): ?><label class="check compact-check"><input type="checkbox" name="allowed_mime_types[]" value="<?= $escape($mime) ?>"<?= $media->allows($mime) ? ' checked' : '' ?>><span><?= $escape($mime) ?></span></label><?php endforeach; ?></div></fieldset>
    <fieldset class="form-card"><legend>Formaty wynikowe</legend><div class="choice-grid"><?php foreach ($formats as $format): ?><label class="check compact-check"><input type="checkbox" name="media_formats[]" value="<?= $escape($format) ?>"<?= $media->allowsFormat($format) ? ' checked' : '' ?>><span><?= strtoupper($format) ?></span></label><?php endforeach; ?></div></fieldset>
</section>
